<script setup lang="ts">
import { computed,onBeforeUnmount,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../api'
import type { PageResponse,ProgressEvent,TaskDetail,TaskReport } from '../types'
import StatusBadge from '../components/StatusBadge.vue'
const originNames:Record<string,string>={synthetic:'合成验证样本',oceanbase:'OceanBase 查询',local_manifest:'本地附件清单',mixed:'多种资料来源'}
const route=useRoute(),task=ref<TaskDetail|null>(null),report=ref<TaskReport|null>(null),activeRun=ref(''),files=ref<PageResponse<Record<string,unknown>>|null>(null),evidence=ref<PageResponse<Record<string,unknown>>|null>(null),gaps=ref<PageResponse<unknown>|null>(null),progress=ref<ProgressEvent[]>([]),loading=ref(true),sectionLoading=ref(false),error=ref(''),tab=ref<'timeline'|'files'|'evidence'|'result'>('result'),evidenceRefs=ref(''),evidenceFile=ref('')
const findingPage=ref<PageResponse<unknown>|null>(null),issuePage=ref<PageResponse<unknown>|null>(null),candidates=ref<PageResponse<unknown>|null>(null)
const visibleFindings=computed(()=>(findingPage.value?.items || report.value?.findings || []) as Record<string,unknown>[])
const visibleIssues=computed(()=>(issuePage.value?.items || report.value?.daily_issues || []) as Record<string,unknown>[])
const issueLabels:Record<string,string>={stop_immediate:'停工响应未满足立即执行要求',power_off_immediate:'断电响应未满足立即执行要求',evacuate:'撤人执行或路线未满足要求',relief_parameters_acceptance:'卸压参数或验收未满足设计要求',personnel_and_equipment:'人员覆盖或设备控制未满足要求'}
function issueLabel(f:Record<string,unknown>){const code=String(f.code||'');return issueLabels[code] || (code.startsWith('below_threshold:')?'效果检验值未低于阈值':code)}
async function pageReportSection(section:string,offset:number){const token=version;try{const r=await api.diagnostics(activeRun.value,section,offset,controller.signal);if(token!==version)return;if(section==='findings')findingPage.value=r;else if(section==='daily_issues')issuePage.value=r;else candidates.value=r;}catch(e){if(token===version)showError(e)}}
async function loadCandidates(event:Event){if((event.target as HTMLDetailsElement).open&&!candidates.value)await pageReportSection('candidates',0)}
let controller=new AbortController(),timer:ReturnType<typeof setTimeout>|undefined,version=0,after=0,nextAfter=0,moreProgress=false,polling=false,progressCursors:number[]=[0]
const selectedItem=computed(()=>task.value?.items.find(item=>item.run_id===activeRun.value))
const queryScope=computed(()=>selectedItem.value?.query_scope)
const progressSummary=computed(()=>selectedItem.value?.progress)
const latestEvent=computed<ProgressEvent|null>(()=>{const event=progressSummary.value?.latest_event || selectedItem.value?.latest_event;if(!event)return null;if(typeof event.event==='object')return {...event.event,sequence:event.sequence,created:event.created};return event as ProgressEvent})
const currentFile=computed(()=>progressSummary.value?.current_file)
const sourceRangeLabel=computed(()=>report.value?.source_complete===false?'资料存在缺口':report.value?.source_complete===true?'已声明完整':progressSummary.value?.catalog_files?'附件范围已登记 · 完整性待核对':'等待登记资料范围')
const stageNames:Record<string,string>={run:'任务执行',source:'输入取证',query:'清单查询',acquisition:'附件取得',parse:'文档解析',recognition:'页面识别',provider:'模型请求',extraction:'事实抽取',evaluation:'规则核验',callback:'结果交付'}
const eventNames:Record<string,string>={claimed:'任务已领取',started:'开始',finished:'完成',source_started:'开始处理资料',source_finished:'资料处理完成',file_started:'开始处理文件',file_finished:'文件处理完成',page_started:'开始处理页面',page_finished:'页面处理完成',provider_finished:'识别服务返回',request_started:'发起识别请求',request_finished:'识别请求返回',cache_reused:'复用解析缓存',extraction_started:'开始抽取事实',extraction_finished:'事实抽取完成'}
const failureReasons:Record<string,string>={DecompressionBombError:'PDF 内嵌图片像素数超过安全限制，该页识别被拒绝。',TimeoutError:'处理超时，请检查对应资料或识别服务。'}
const failureReason=computed(()=>report.value?.error_type?failureReasons[report.value.error_type] || `处理异常：${report.value.error_type}`:'')
const alive=computed(()=>task.value?.items.some(i=>['queued','running'].includes(i.execution_state)))
function value(item:Record<string,unknown>,key:string){const v=item[key];return v===null||v===undefined?'—':typeof v==='object'?JSON.stringify(v):String(v)}
function duration(ms?:number|null){return ms===undefined||ms===null?'—':ms<1000?`${Math.round(ms)} ms`:ms<60000?`${(ms/1000).toFixed(1)} 秒`:`${Math.floor(ms/60000)} 分 ${Math.round(ms%60000/1000)} 秒`}
function eventLabel(event:ProgressEvent|null){return event?`${stageNames[event.stage || ''] || event.stage || '任务'} · ${eventNames[event.event || ''] || event.event || '状态更新'}`:'尚无阶段事件'}
function localTime(epoch?:number){return epoch?new Date(epoch*1000).toLocaleTimeString('zh-CN',{hour12:false}):'—'}
function showError(e:unknown){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'请求失败，请重试'}
async function chooseRun(runId:string){const token=++version;activeRun.value=runId;report.value=null;findingPage.value=null;issuePage.value=null;candidates.value=null;files.value=null;evidence.value=null;gaps.value=null;progress.value=[];after=0;nextAfter=0;progressCursors=[0];moreProgress=false;evidenceRefs.value='';evidenceFile.value='';sectionLoading.value=true;try{const r=await api.report(runId,controller.signal);if(token===version)report.value=r;await loadSection(token)}catch(e){if(token===version)showError(e)}finally{if(token===version)sectionLoading.value=false}}
async function loadSection(token=version){if(!activeRun.value||token!==version)return;sectionLoading.value=true;try{if(tab.value==='files'&&!files.value){const r=await api.files(activeRun.value,0,controller.signal);if(token===version)files.value=r}else if(tab.value==='evidence'&&!evidence.value){const r=await api.evidence(activeRun.value,0,evidenceRefs.value,evidenceFile.value,controller.signal);if(token===version)evidence.value=r}else if(tab.value==='timeline'&&!progress.value.length){await loadProgress(token)}}catch(e){showError(e)}finally{if(token===version)sectionLoading.value=false}}
async function loadProgress(token=version){const r=await api.progress(activeRun.value,after,controller.signal);if(token!==version)return;progress.value=r.events||[];nextAfter=r.next_after??after;moreProgress=!!r.has_more}
async function setTab(next:typeof tab.value){tab.value=next;await loadSection()}
async function pageFiles(offset:number){const token=version,runId=activeRun.value;sectionLoading.value=true;try{const r=await api.files(runId,offset,controller.signal);if(token===version)files.value=r}catch(e){if(token===version)showError(e)}finally{if(token===version)sectionLoading.value=false}}
async function pageEvidence(offset:number){const token=version,runId=activeRun.value;sectionLoading.value=true;try{const r=await api.evidence(runId,offset,evidenceRefs.value,evidenceFile.value,controller.signal);if(token===version)evidence.value=r}catch(e){if(token===version)showError(e)}finally{if(token===version)sectionLoading.value=false}}
async function inspectEvidence(finding:Record<string,unknown>){evidenceRefs.value=Array.isArray(finding.evidence_refs)?finding.evidence_refs.map(String).join(','):'';evidenceFile.value='';evidence.value=null;await setTab('evidence')}
async function inspectFile(file:Record<string,unknown>){evidenceFile.value=String(file.file_id||'');evidenceRefs.value='';evidence.value=null;await setTab('evidence')}
async function pageGaps(offset:number){const token=version,runId=activeRun.value;try{const r=await api.diagnostics(runId,'gaps',offset,controller.signal);if(token===version)gaps.value=r}catch(e){if(token===version)showError(e)}}
async function loadGaps(event:Event){if(!(event.target as HTMLDetailsElement).open||gaps.value)return;await pageGaps(0)}
async function nextProgress(){after=nextAfter;progressCursors.push(after);try{await loadProgress()}catch(e){showError(e)}}
async function previousProgress(){if(progressCursors.length>1)progressCursors.pop();after=progressCursors.at(-1)||0;try{await loadProgress()}catch(e){showError(e)}}
async function poll(){if(polling||controller.signal.aborted||!alive.value)return;if(document.hidden){timer=setTimeout(poll,3000);return;}polling=true;const token=version,runId=activeRun.value;try{const fresh=await api.task(String(route.params.recordId),controller.signal);if(token!==version)return;task.value=fresh;const r=await api.report(runId,controller.signal);if(token===version)report.value=r}catch(e){if(token===version)showError(e)}finally{polling=false;if(alive.value&&!controller.signal.aborted)timer=setTimeout(poll,3000)}}
async function loadTask(){clearTimeout(timer);controller.abort();controller=new AbortController();version++;loading.value=true;error.value='';task.value=null;try{task.value=await api.task(String(route.params.recordId),controller.signal);if(task.value.items[0])await chooseRun(task.value.items[0].run_id);if(alive.value)timer=setTimeout(poll,3000)}catch(e){showError(e)}finally{loading.value=false}}
watch(()=>route.params.recordId,loadTask,{immediate:true});onBeforeUnmount(()=>{controller.abort();clearTimeout(timer);version++})
</script>
<template>
  <section class="page-stack"><div v-if="loading" class="loading-line">正在加载任务摘要…</div><p v-if="error" class="error-banner">{{ error }} <button class="text-button" @click="loadTask">重试</button></p><template v-if="task&&!loading">
    <div class="page-intro"><div><RouterLink to="/tasks" class="back-link">← 返回任务记录</RouterLink><h2>{{ task.mine_code }} · {{ task.check_cycle }}</h2><p class="muted mono">{{ task.record_id }}</p></div><div class="inline-actions"><RouterLink v-if="task.request?.manifestPath || task.request?.dataSource==='oceanbase'" class="button secondary" :to="{path:'/trigger',query:{from:task.record_id}}">用本轮参数新建任务</RouterLink><StatusBadge :status="selectedItem?.result_status || task.execution_state" /></div></div>
    <div class="task-context"><span>{{ new Date(task.created*1000).toLocaleString('zh-CN',{hour12:false}) }} 触发</span><span>{{ originNames[task.origin || ''] || task.source_system }}</span><span>总耗时 {{ duration(task.elapsed_ms) }}</span><span>本地结果 · 回调关闭</span></div>
    <div class="detail-grid"><aside class="panel run-picker"><p class="picker-title">检查项</p><button v-for="item in task.items" :key="item.run_id" class="run-picker-item" :class="{selected:activeRun===item.run_id}" @click="chooseRun(item.run_id)"><strong>{{ item.item_name || item.item_code }}</strong><small class="mono">{{ item.item_code }}</small><StatusBadge :status="item.result_status || item.execution_state" /></button></aside>
    <div class="panel detail-main"><div class="summary-strip"><div><span>当前结论</span><strong>{{ report?.description || selectedItem?.description || '结果尚未定版' }}</strong></div><div><span>资料范围</span><strong>{{ sourceRangeLabel }}</strong></div><div><span>执行状态</span><StatusBadge :status="selectedItem?.execution_state" /></div></div>
    <div v-if="queryScope" class="query-scope" :class="{mismatch:queryScope.differs_from_task}"><div><span>实际取数周期</span><strong>{{ queryScope.resolved_cycle || '等待确定' }}</strong><small v-if="queryScope.period?.start">{{ queryScope.period.start }} 至 {{ queryScope.period.end }}</small></div><p v-if="queryScope.differs_from_task">任务报文周期为 {{ queryScope.requested_cycle || task.check_cycle }}。本次沿用已冻结的历史查询范围；新任务将按传入周期取数。</p><p v-else>{{ queryScope.source==='frozen_query'?'本次查询范围已冻结。':'受理时已确定取数周期，等待查询。' }}</p></div>
    <div v-if="progressSummary || latestEvent" class="execution-summary"><div class="execution-summary-head"><h3>{{ alive?'当前进度':'执行摘要' }}</h3><small>最近更新 {{ localTime(latestEvent?.created) }}</small></div><dl v-if="progressSummary" class="execution-counts"><div><dt>附件冻结</dt><dd>{{ progressSummary.downloaded ?? 0 }} / {{ progressSummary.catalog_files ?? 0 }}<small v-if="progressSummary.download_failed"> · {{ progressSummary.download_failed }} 份失败</small></dd></div><div><dt>文件处理</dt><dd>{{ progressSummary.processed_files ?? 0 }} / {{ progressSummary.downloaded ?? progressSummary.catalog_files ?? 0 }}</dd></div><div><dt>页面识别</dt><dd>已处理 {{ progressSummary.recognition_pages_completed ?? 0 }} 页<small v-if="progressSummary.recognition_pages_failed"> · {{ progressSummary.recognition_pages_failed }} 页失败</small></dd></div></dl><p class="current-operation"><strong>{{ eventLabel(latestEvent) }}</strong><span v-if="currentFile?.file_name || currentFile?.file_id">{{ currentFile.file_name || currentFile.file_id }}<template v-if="currentFile.page"> · 第 {{ currentFile.page }}<template v-if="currentFile.page_total"> / {{ currentFile.page_total }}</template> 页</template></span><span v-else-if="latestEvent?.file_id">{{ latestEvent.file_name || latestEvent.file_id }}<template v-if="latestEvent.page"> · 第 {{ latestEvent.page }} 页</template></span></p><p v-if="latestEvent?.issues?.length" class="event-issues">{{ latestEvent.issues.join('；') }}</p></div>
    <nav class="detail-tabs" aria-label="任务详情区域"><button :class="{active:tab==='result'}" @click="setTab('result')">结果与问题</button><button :class="{active:tab==='timeline'}" @click="setTab('timeline')">执行链路</button><button :class="{active:tab==='files'}" @click="setTab('files')">涉及附件</button><button :class="{active:tab==='evidence'}" @click="setTab('evidence')">证据溯源</button></nav>
    <div v-if="sectionLoading" class="loading-line">正在加载此区域…</div>
    <div v-else-if="tab==='result'" class="result-section"><div class="result-card"><StatusBadge :status="report?.status"/><h3>{{ report?.description || '检查正在进行' }}</h3><template v-if="report?.status==='failed'"><p>{{ failureReason || report?.detail }}</p><p v-if="report?.failure_location">文件：{{ report.failure_location.file_name || report.failure_location.file_id }}<span v-if="report.failure_location.page"> · 第 {{ report.failure_location.page }} 页</span><br>附件 ID：{{ report.failure_location.file_id }}</p><p>失败阶段：{{ stageNames[report.error_stage || ''] || report.error_stage || '未知' }}。本次没有形成业务核验结论。</p></template><p v-else>{{ report?.detail || '定版结果将在规则评估完成后显示。' }}</p></div>
      <article v-for="(finding,index) in visibleFindings" :key="index" class="finding-card"><div class="finding-head"><h3>{{ value(finding,'workface')==='—'?'问题记录':`${value(finding,'workface')} 工作面` }}</h3><StatusBadge status="no_pass" /></div><p class="finding-code">{{ finding.event_time || finding.date_start || finding.date || '' }} {{ issueLabel(finding) }}</p><p>{{ finding.description || finding.detail || '详见对应命题和原文依据。' }}</p><button v-if="Array.isArray(finding.evidence_refs)&&finding.evidence_refs.length" class="text-button" @click="inspectEvidence(finding)">查看 {{ finding.evidence_refs.length }} 条原文依据 →</button><p v-else class="field-help">当前问题未提供原文引用。</p></article>
      <div v-if="(report?.finding_count || 0)>100 || findingPage" class="pagination"><button v-if="!findingPage" class="button secondary" @click="pageReportSection('findings',0)">分页查看全部 {{ report?.finding_count }} 个问题</button><template v-else><button class="button secondary" :disabled="findingPage.offset===0" @click="pageReportSection('findings',Math.max(0,findingPage.offset-findingPage.limit))">上一页</button><span>共 {{ findingPage.total }} 个问题</span><button class="button secondary" :disabled="!findingPage.has_more" @click="pageReportSection('findings',findingPage.offset+findingPage.limit)">下一页</button></template></div><div v-if="!report?.findings?.length && report?.status && report.status!=='failed'" class="detail-hint">本次未形成确定性不合规问题。请结合资料缺口和候选查看结论。</div>
      <article v-for="(issue,index) in visibleIssues" :key="index" class="finding-card candidate"><div class="finding-head"><h3>{{ issue.date_start || issue.date || '日期未绑定' }} · {{ issue.workface || '工作面未绑定' }}</h3><span class="status-badge" data-status="pending">{{ issue.certainty==='confirmed'?'已确认记录':'候选 / 待核实' }}</span></div><p>{{ issue.description }}</p><button v-if="Array.isArray(issue.evidence_refs)&&issue.evidence_refs.length" class="text-button" @click="inspectEvidence(issue)">查看原文线索 →</button></article>
      <div v-if="(report?.daily_issue_count || 0)>100 || issuePage" class="pagination"><button v-if="!issuePage" class="button secondary" @click="pageReportSection('daily_issues',0)">分页查看全部 {{ report?.daily_issue_count }} 条日级记录</button><template v-else><button class="button secondary" :disabled="issuePage.offset===0" @click="pageReportSection('daily_issues',Math.max(0,issuePage.offset-issuePage.limit))">上一页</button><span>共 {{ issuePage.total }} 条</span><button class="button secondary" :disabled="!issuePage.has_more" @click="pageReportSection('daily_issues',issuePage.offset+issuePage.limit)">下一页</button></template></div>
      <details class="diagnostic-block" @toggle="loadCandidates"><summary>未确认的识别候选（{{ report?.counts?.candidates || 0 }}）</summary><p class="field-help">候选用于回溯识别内容，不是确定性预警或违规事实。</p><details v-for="(candidate,index) in candidates?.items || []" :key="index" class="evidence-card"><summary>识别候选 {{ (candidates?.offset || 0)+index+1 }}</summary><pre>{{ JSON.stringify(candidate,null,2) }}</pre></details><div v-if="candidates" class="pagination"><button class="button secondary" :disabled="candidates.offset===0" @click="pageReportSection('candidates',Math.max(0,candidates.offset-candidates.limit))">上一页</button><span>共 {{ candidates.total }} 条</span><button class="button secondary" :disabled="!candidates.has_more" @click="pageReportSection('candidates',candidates.offset+candidates.limit)">下一页</button></div></details>
      <details class="diagnostic-block" @toggle="loadGaps"><summary>资料缺口与未闭合条件（{{ report?.counts?.gaps || 0 }}）</summary><ul v-if="gaps"><li v-for="(gap,index) in gaps.items" :key="index">{{ typeof gap==='string'?gap:JSON.stringify(gap) }}</li></ul><div v-if="gaps" class="pagination"><button class="button secondary" :disabled="gaps.offset===0" @click="pageGaps(Math.max(0,gaps.offset-gaps.limit))">上一页</button><span>共 {{ gaps.total }} 项</span><button class="button secondary" :disabled="!gaps.has_more" @click="pageGaps(gaps.offset+gaps.limit)">下一页</button></div></details>
      <details class="diagnostic-block"><summary>任务输入与查询范围</summary><pre>{{ JSON.stringify({request:task.request,query_policy:task.query_policy,observation:report?.observation},null,2) }}</pre></details>
    </div>
    <div v-else-if="tab==='timeline'" class="timeline"><div class="history-toolbar"><p>历史执行事件按发生顺序分页。最新处理位置见上方进度摘要。</p><button class="text-button" @click="loadProgress()">刷新本页</button></div><div v-for="event in progress" :key="event.sequence" class="timeline-item"><span class="timeline-dot" :data-status="event.status"/><div><strong>{{ stageNames[event.stage || ''] || event.stage }} · {{ eventNames[event.event || ''] || event.event }}</strong><p>{{ event.file_id || '任务级事件' }}<span v-if="event.page"> · 第 {{ event.page }} 页</span><span v-if="event.provider"> · {{ event.provider }}</span></p><small>{{ event.status || 'running' }} · {{ event.created?new Date(event.created*1000).toLocaleTimeString('zh-CN',{hour12:false}):'' }}<span v-if="event.elapsed_ms!==undefined"> · {{ duration(event.elapsed_ms) }}</span></small><p v-if="event.issues?.length" class="event-issues">{{ event.issues.join('；') }}</p></div></div><p v-if="!progress.length" class="detail-hint">暂无阶段事件。任务执行后将按阶段记录进度。</p><div class="pagination"><button class="button secondary" :disabled="progressCursors.length<=1" @click="previousProgress">较早事件</button><span>第 {{ progressCursors.length }} 页 · {{ progress.length }} 条</span><button class="button secondary" :disabled="!moreProgress" @click="nextProgress">后续事件</button></div><p v-if="alive" class="field-help">上方最新进度每 3 秒刷新；历史事件按需加载，离开页面即停止轮询。</p></div>
    <div v-else-if="tab==='files'" class="data-list"><div v-for="file in files?.items" :key="value(file,'file_id')" class="data-row"><strong>{{ file.original_name || file.attachment_name || file.file_id }}</strong><span>{{ file.material_group || file.role || '资料' }} · {{ file.status || '已登记' }}</span><small v-if="file.error" class="event-issues">{{ file.error }}</small><small>日期 {{ file.report_date || '未绑定' }} · {{ file.evidence_count || 0 }} 条证据</small><small>SHA256 {{ file.content_hash || '未取得字节' }}</small><details class="file-metadata"><summary>来源标识</summary><pre>{{ JSON.stringify({file_id:file.file_id,report_date:file.report_date,...(typeof file.source_metadata==='object'&&file.source_metadata?file.source_metadata:{})},null,2) }}</pre></details><button class="text-button" @click="inspectFile(file)">查看此文件证据</button></div><p v-if="!files?.items.length" class="detail-hint">当前尚无附件摘要。</p><div v-if="files" class="pagination"><button class="button secondary" :disabled="files.offset===0" @click="pageFiles(Math.max(0,files.offset-files.limit))">上一页</button><span>共 {{ files.total }} 份</span><button class="button secondary" :disabled="!files.has_more" @click="pageFiles(files.offset+files.limit)">下一页</button></div></div>
    <div v-else class="data-list"><div v-if="evidenceRefs||evidenceFile" class="filter-note">正在查看选定{{ evidenceFile?'文件':'问题' }}的原文 <button class="text-button" @click="evidenceRefs='';evidenceFile='';pageEvidence(0)">查看全部</button></div><details v-for="item in evidence?.items" :key="value(item,'evidence_id')" class="evidence-card"><summary>{{ item.original_name || item.file_id }} · {{ value(item,'locator') }}<span v-if="item.is_candidate || item.quality==='candidate'" class="status-badge" data-status="pending">识别候选</span></summary><p v-if="item.is_candidate || item.quality==='candidate'" class="field-help">以下为尚未确认的识别片段，仅用于核对来源，不能证明预警或违规。</p><p>{{ item.text }}</p><small>证据 {{ item.evidence_id }}<br>来源 {{ item.source_role }} · 哈希 {{ item.content_hash }}</small></details><p v-if="!evidence?.items.length" class="detail-hint">当前没有已登记的原文证据。</p><div v-if="evidence" class="pagination"><button class="button secondary" :disabled="evidence.offset===0" @click="pageEvidence(Math.max(0,evidence.offset-evidence.limit))">上一页</button><span>共 {{ evidence.total }} 条</span><button class="button secondary" :disabled="!evidence.has_more" @click="pageEvidence(evidence.offset+evidence.limit)">下一页</button></div></div>
    </div></div>
  </template></section>
</template>
